type Props = ComponentProps<typeof PromoCardDesktop>;

// Ассет должен соответствовать выбранному ImageView, включая Crop/Segment. Card action, CTA handlers и bottomAddon задаёт приложение.
function Example({ image, cardAction }: {
    image: NonNullable<Props['image']>;
    cardAction?: { onClick: NonNullable<Props['onClick']> };
}) {
    return <PromoCardDesktop
        size="small"
        title={"Title 22-26"}
        subtitle={"Subtitle 16-24"}
        titleView="primary"
        centred={false}
        clickable={cardAction !== undefined}
        onClick={cardAction?.onClick}
        image={image} imageOrientation="bottom" imageCrop={false} imageOffset={false} imageAlign="normal"



        backgroundPlateProps={{ children: undefined, promo: true, level: 'outer', backgroundColor: "base-bg-alt", showSkeleton: false }}
    />;
}

